    40	/**
    41	 * gnutls_idna_map:
    42	 * @input: contain the UTF-8 formatted domain name
    43	 * @ilen: the length of the provided string
    44	 * @out: the result in an null-terminated allocated string
    45	 * @flags: should be zero
    46	 *
    47	 * This function will convert the provided UTF-8 domain name, to
    48	 * its IDNA mapping in an allocated variable. Note that depending on the flags the used gnutls
    49	 * library was compiled with, the output of this function may vary (i.e.,
    50	 * may be IDNA2008, or IDNA2003).
    51	 *
    52	 * To force IDNA2008 specify the flag %GNUTLS_IDNA_FORCE_2008. In
    53	 * the case GnuTLS is not compiled with the necessary dependencies,
    54	 * %GNUTLS_E_UNIMPLEMENTED_FEATURE will be returned to indicate that
    55	 * gnutls is unable to perform the requested conversion.
    56	 *
    57	 * Note also, that this function will return an empty string if an
    58	 * empty string is provided as input.
    59	 *
    60	 * Returns: %GNUTLS_E_INVALID_UTF8_STRING on invalid UTF-8 data, or 0 on success.
    61	 *
    62	 * Since: 3.5.8
    63	 **/
    64	int gnutls_idna_map(const char *input, unsigned ilen, gnutls_datum_t *out, unsigned flags)
    65	{
    66	        char *idna = NULL;
    67	        int rc, ret;
    68	        gnutls_datum_t istr;
    69	        unsigned int idn2_flags = IDN2_NFC_INPUT;
    70	        unsigned int idn2_tflags = IDN2_NFC_INPUT;
    71	
    72	#if IDN2_VERSION_NUMBER >= 0x00140000
    73	        /* IDN2_NONTRANSITIONAL automatically converts to lowercase
    74	         * IDN2_NFC_INPUT converts to NFC before toASCII conversion
    75	         *
    76	         * Since IDN2_NONTRANSITIONAL implicitly does NFC conversion, we don't need
    77	         * the additional IDN2_NFC_INPUT. But just for the unlikely case that the linked
    78	         * library is not matching the headers when building and it doesn't support TR46,
    79	         * we provide IDN2_NFC_INPUT. */
    80	        idn2_flags |= IDN2_NONTRANSITIONAL;
    81	        idn2_tflags |= IDN2_TRANSITIONAL;
    82	#endif
    83	
    84	        /* This avoids excessive CPU usage with libidn2 < 2.1.1 */
    85	        if (ilen > 2048) {
    86	                gnutls_assert();
    87	                _gnutls_debug_log("unable to convert name '%.*s' to IDNA format: %s\n",
    88	                        (int) ilen, input, idn2_strerror(IDN2_TOO_BIG_DOMAIN));
    89	                return GNUTLS_E_INVALID_UTF8_STRING;
    90	        }
    91	
    92	        if (ilen == 0) {
    93	                out->data = (uint8_t*)gnutls_strdup("");
    94	                out->size = 0;
    95	                if (out->data == NULL)
    96	                        return gnutls_assert_val(GNUTLS_E_MEMORY_ERROR);
    97	                return 0;
    98	        }
    99	
   100	        if (_gnutls_str_is_print(input, ilen)) {
   101	                return _gnutls_set_strdatum(out, input, ilen);
   102	        }
   103	
   104	        ret = _gnutls_set_strdatum(&istr, input, ilen);
   105	        if (ret < 0) {
   106	                gnutls_assert();
   107	                return ret;
   108	        }
   109	
   110	        rc = idn2_to_ascii_8z((ICAST*)istr.data, (ICAST**)&idna, idn2_flags);
   111	        if (rc == IDN2_DISALLOWED && !(flags & GNUTLS_IDNA_FORCE_2008))
   112	                rc = idn2_to_ascii_8z((ICAST*)istr.data, (ICAST**)&idna, idn2_tflags);
   113	
   114	        if (rc != IDN2_OK) {
   115	                gnutls_assert();
   116	                idna = NULL; /* in case idn2_lookup_u8 modifies &idna */
   117	                _gnutls_debug_log("unable to convert name '%s' to IDNA format: %s\n", istr.data, idn2_strerror(rc));
   118	                ret = GNUTLS_E_INVALID_UTF8_STRING;
   119	                goto fail;
   120	        }
   121	
   122	        if (gnutls_free != idn2_free) {
   123	                ret = _gnutls_set_strdatum(out, idna, strlen(idna));
   124	        } else  {
   125	                out->data = (unsigned char*)idna;
   126	                out->size = strlen(idna);
   127	                idna = NULL;
   128	                ret = 0;
   129	        }
   130	
   131	 fail:
   132	        idn2_free(idna);
   133	        gnutls_free(istr.data);
   134	        return ret;
   135	}
